# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 12)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(5, 60)]
        self.assertEqual(
            round_labels(spans, 10), ["00:10-01:00 (0h 50m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
